-- 20,000 products with distinct Amazon Berkeley Objects catalog image URLs.
-- Dataset attribution and license are documented in README-attribution.txt.
BEGIN;

CREATE TEMP TABLE seed_products (
  row_no integer PRIMARY KEY, product_name varchar(255), description varchar(255),
  discount float8 NOT NULL, image varchar(255), price float8 NOT NULL,
  quantity int4, special_price float8 NOT NULL, category_name varchar(255)
) ON COMMIT DROP;


SELECT DISTINCT s.category_name FROM seed_products s
WHERE NOT EXISTS (SELECT 1 FROM public.categories c WHERE c.category_name = s.category_name);

WITH product_id_base AS (
  SELECT COALESCE(MAX(product_id), 0) AS max_id FROM public.products
)
SELECT b.max_id + s.row_no, s.description, s.discount, s.image, s.price, s.product_name,
       s.quantity, s.special_price, c.category_id, ((s.row_no - 1) % 10) + 1
FROM seed_products s CROSS JOIN product_id_base b
JOIN LATERAL (SELECT MIN(category_id) AS category_id FROM public.categories WHERE category_name = s.category_name) c ON TRUE
ORDER BY s.row_no;

DO $$ DECLARE seq_name text; BEGIN
  seq_name := pg_get_serial_sequence('public.products', 'product_id');
  IF seq_name IS NOT NULL THEN
    PERFORM setval(seq_name, (SELECT COALESCE(MAX(product_id), 1) FROM public.products), true);
  END IF;
END $$;

COMMIT;
